<?php require dirname(__DIR__,2).'/layouts/admin_start.php';$editing=!empty($lot['id']); ?><link rel="stylesheet" href="/assets/css/supplies.css">
<section class="content-card form-card"><div class="section-heading"><div><span class="eyebrow">Insumo: <?= htmlspecialchars($supply['name'],ENT_QUOTES,'UTF-8') ?></span><h2><?= $editing?'Editar lote':'Cadastrar lote' ?></h2><p>Informe validade, recebimento e quantidades disponíveis.</p></div><a class="button button-secondary" href="/admin/supplies/lots?supply_id=<?= (int)$supply['id'] ?>">Voltar</a></div><?php if($errors): ?><div class="alert alert-error"><ul><?php foreach($errors as $error): ?><li><?= htmlspecialchars($error,ENT_QUOTES,'UTF-8') ?></li><?php endforeach; ?></ul></div><?php endif; ?>
